{
  "root_causes": [
    {
      "service": "search",
      "fault_kind": "pod_unavailable",
      "evidence": [
        {"kind": "metric", "sql": "SELECT 'abn' p, attr_k8s_pod_name pod, metric, count(*) n, max(value) maxv FROM abnormal_metrics WHERE metric='k8s.container.restarts' AND attr_k8s_pod_name LIKE 'search-%' GROUP BY 1,2,3 UNION ALL SELECT 'norm', attr_k8s_pod_name, metric, count(*), max(value) FROM normal_metrics WHERE metric='k8s.container.restarts' AND attr_k8s_pod_name LIKE 'search-%' GROUP BY 1,2,3", "claim": "The search pod's restart counter reached 6 during the incident (0 in normal), showing a crash loop."},
        {"kind": "metric", "sql": "SELECT date_trunc('minute', time) t, service_name, metric, round(avg(value),1) v FROM abnormal_metrics WHERE service_name='search' AND metric='k8s.deployment.available' GROUP BY 1,2,3 ORDER BY 1", "claim": "Search deployment reports 0 available replicas in every abnormal minute, versus 1 in normal."},
        {"kind": "trace", "sql": "SELECT service_name, count(*) n FROM abnormal_traces WHERE service_name='search' GROUP BY 1", "claim": "Search emitted no spans at all during the abnormal window, while it produced about 980 spans in normal."},
        {"kind": "log", "sql": "SELECT regexp_extract(message,'\"reason\":\"([^\"]+)\"',1) reason, regexp_extract(message,'\"name\":\"([^\"]+)\"',1) objname, count(*) n FROM abnormal_logs WHERE service_name='' OR service_name IS NULL GROUP BY 1,2 ORDER BY n DESC LIMIT 30", "claim": "Kubernetes events show search-6d9bbc4fdd-ngg5c with BackOff, Failed, Killing and repeated restarts."}
      ]
    }
  ],
  "propagation": [
    {"from": "search", "to": "frontend", "evidence": [{"kind": "trace", "sql": "SELECT service_name, span_name, attr_http_response_status_code sc, count(*) n, round(avg(duration)/1e6,3) avg_ms FROM abnormal_traces WHERE (service_name='frontend' AND span_name IN ('HTTP /hotels','search.Search/Nearby')) GROUP BY 1,2,3 ORDER BY 1,2,3", "claim": "All 780 frontend /hotels requests return 500 after a near-instant failed search.Search/Nearby call."}]}
  ]
}
